def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    for string in lst:
        if not all(char in ['(', ')'] for char in string):
            return 'No'

    count = 0
    for char in ''.join(lst):
        if char == '(':
            count += 1
        else:
            count -= 1
        if count < 0:
            return 'No'

    return 'Yes'
